function longestSteady(nums: number[], limit: number): number {
  const maxQ: number[] = [], minQ: number[] = [];
  let maxH = 0, minH = 0, l = 0, best = 0; // head indexes stand in for shift()
  for (let r = 0; r < nums.length; r++) {
    while (maxQ.length > maxH && nums[maxQ[maxQ.length - 1]] < nums[r]) maxQ.pop();
    maxQ.push(r);
    while (minQ.length > minH && nums[minQ[minQ.length - 1]] > nums[r]) minQ.pop();
    minQ.push(r);
    while (nums[maxQ[maxH]] - nums[minQ[minH]] > limit) {
      l++;
      if (maxQ[maxH] < l) maxH++;
      if (minQ[minH] < l) minH++;
    }
    best = Math.max(best, r - l + 1);
  }
  return best;
}

