class Solution:
    def longestSteady(self, nums: List[int], limit: int) -> int:
        max_q, min_q = deque(), deque()
        l = best = 0
        for r, x in enumerate(nums):
            while max_q and nums[max_q[-1]] < x:
                max_q.pop()
            max_q.append(r)
            while min_q and nums[min_q[-1]] > x:
                min_q.pop()
            min_q.append(r)
            while nums[max_q[0]] - nums[min_q[0]] > limit:
                l += 1
                if max_q[0] < l:
                    max_q.popleft()
                if min_q[0] < l:
                    min_q.popleft()
            best = max(best, r - l + 1)
        return best

